 500                                // Time (in milliseconds) to pause between pixels\n\nconst int sampleRate = 16000;                         // sample rate in Hz\nconst int frequency = 440;                            // frequency of square wave in Hz\nconst int amplitude = 500;                            // amplitude of square wave\nint32_t sample = amplitude;                           // current sample value\nconst int halfWavelength = sampleRate / frequency;    // half wavelength of square wave\n\nbool i2s_rgb = true;\n\n\nvoid setup() {\n  Serial.begin(115200);\n//  while(!Serial);             // Wait for the serial port to connect\n\n  strip.begin();\n  strip.show();\n  strip.setBrightness(20);\n\n  I2S.setPins(8, 7, 43, 44);  // Configure I2S pins\n  if (!I2S.begin(I2S_MODE_STD, sampleRate, I2S_DATA_BIT_WIDTH_16BIT, I2S_SLOT_MODE_STEREO)){\n    Serial.println("Failed to initialize I2S!");\n    while(1);                 // Halt if failed to initialize\n  }\n}\n\nvoid loop() {\n  int32_t sample_read;\n  uint32_t sum = 0;\n  int count = 0;\n\n  // Reading audio data from I2S\n  for (int i = 0; i < 1024; i++) {\n    sample_read = I2S.read();\n    if (sample_read != 0 && sample_read != 0xFFFF){\n      sum += abs(sample_read);  // Calculating Absolute Value Sums\n      count++;\n    }\n  }\n\n  int average = sum / count;    // Calculation of average intensity\n  Serial.println(average);\n\n  int activeLEDs = map(average, 30000, 36000, 0, NUMPIXELS);  // Mapping average to LED quantity, value to map, value current range, value target range after mapping\n\n  // Update LED strip brightness and colour\n  for (int i = 0; i < NUMPIXELS; i++) {\n    if (i < activeLEDs) {\n      // Setting the colour according to the LED position\n      int colorIntensity = map(i, 0, NUMPIXELS - 1, 0, 255);\n      strip.setPixelColor(i, strip.Color(0, colorIntensity, 255 - colorIntensity));  // Transition from blue to green\n    } else {\n      strip.setPixelColor(i, strip.Color(0, 0, 0));  // Switching off inactive LEDs\n    }\n  }\n  strip.show();\n\n  delay(100);\n}\n'})}),"\n",(0,r.jsx)(n.h3,{id:"personalizaci\xf3n",children:"Personalizaci\xf3n"}),"\n",(0,r.jsx)(n.p,{children:"Puedes personalizar el comportamiento de la tira NeoPixel reactiva al audio modificando los siguientes par\xe1metros:"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.code,{children:"DELAYVAL"}),": El tiempo de retraso (en milisegundos) entre cada actualizaci\xf3n de p\xedxel (por defecto: 500)\n",(0,r.jsx)(n.code,{children:"Rango de mapeo para activeLEDs"}),": Ajusta el rango de valores de intensidad promedio para mapear al n\xfamero de LEDs activos (por defecto: 30000 a 36000)\n",(0,r.jsx)(n.code,{children:"Esquema de colores"}),": Modifica la funci\xf3n strip.setPixelColor() para cambiar la transici\xf3n de color o usar diferentes colores para los LEDs"]})]})}function p(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},71184(e,n,i){i.d(n,{R:()=>t,x:()=>o});var a=i(14041);let r={},s=a.createContext(r);function t(e){let n=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:t(e.components),a.createElement(s.Provider,{value:n},e.children)}}}]);